//! Fixture-based integration tests for the extraction layer
//! (`cargo test -p difflens-core`). Fixtures are tiny committed binaries
//! generated by `scripts/gen-fixtures/generate.py`.

use std::io::Write;
use std::path::PathBuf;

use difflens_core::extract::extract;
use difflens_core::model::{BlockKind, DocFormat};

fn fixture(name: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join(name);
    path.to_str().unwrap().to_string()
}

/// CI sets DIFFLENS_PDFIUM_STRICT=1 after staging PDFium: there a missing
/// library must fail the job instead of skipping the assertions.
fn pdf_strict() -> bool {
    std::env::var("DIFFLENS_PDFIUM_STRICT").is_ok()
}

fn extract_pdf_or_skip(name: &str) -> Option<difflens_core::DocumentModel> {
    match extract(&fixture(name)) {
        Ok(model) => Some(model),
        Err(e) => {
            let msg = e.to_string();
            let library_missing =
                msg.contains("PDFium library not found") || msg.contains("could not be bound");
            if !library_missing {
                panic!("pdf extraction failed unexpectedly: {e}");
            }
            if pdf_strict() {
                panic!("DIFFLENS_PDFIUM_STRICT is set but PDFium is missing: {e}");
            }
            eprintln!("skipping pdf fixture assertions ({name}): {msg}");
            None
        }
    }
}

// --------------------------------------------------------------------------
// TXT
// --------------------------------------------------------------------------

#[test]
fn txt_extracts_headings_and_paragraphs() {
    let model = extract(&fixture("sample.txt")).unwrap();
    assert_eq!(model.format, DocFormat::Txt);
    assert_eq!(model.page_count, None);
    assert!(model.warnings.is_empty());
    let kinds: Vec<&BlockKind> = model.blocks.iter().map(|b| &b.kind).collect();
    assert_eq!(
        kinds,
        vec![
            &BlockKind::Heading { level: 1 },
            &BlockKind::Paragraph,
            &BlockKind::Paragraph,
            &BlockKind::Heading { level: 2 },
            &BlockKind::Paragraph,
        ]
    );
    assert_eq!(model.blocks[0].text, "Report");
    assert_eq!(model.blocks[1].text, "First paragraph with a short line.");
    assert_eq!(
        model.blocks[2].text,
        "Second paragraph that continues on a second physical line."
    );
    assert_eq!(model.blocks[3].text, "Details");
    assert_eq!(
        model.blocks[4].text,
        "Final body paragraph mentioning 100 USD and 2026-01-15."
    );
    let ids: Vec<&str> = model.blocks.iter().map(|b| b.id.as_str()).collect();
    assert_eq!(ids, vec!["b0", "b1", "b2", "b3", "b4"]);
    assert!(model.blocks[0].page.is_none());
}

#[test]
fn txt_empty_document_yields_no_blocks() {
    let model = extract(&fixture("empty.txt")).unwrap();
    assert!(model.blocks.is_empty());
    assert!(model.warnings.is_empty());
}

#[test]
fn txt_vietnamese_nfd_is_normalized_to_nfc() {
    let model = extract(&fixture("vietnamese.txt")).unwrap();
    assert_eq!(model.blocks[0].text, "Xin chào");
    assert_eq!(model.blocks[1].text, "Đây là văn bản tiếng Việt có dấu.");
}

// --------------------------------------------------------------------------
// PDF (skips gracefully without the staged PDFium library)
// --------------------------------------------------------------------------

#[test]
fn pdf_extracts_paragraphs_pages_and_scanned_warning() {
    let Some(model) = extract_pdf_or_skip("sample.pdf") else {
        return;
    };
    eprintln!("pdf-extraction-ok: extracted {} blocks", model.blocks.len());
    assert_eq!(model.format, DocFormat::Pdf);
    assert_eq!(model.page_count, Some(3));

    // Page 1: title paragraph + two-line merged paragraph + third paragraph.
    let page1: Vec<&difflens_core::Block> =
        model.blocks.iter().filter(|b| b.page == Some(1)).collect();
    assert_eq!(page1.len(), 3, "page 1 blocks: {page1:?}");
    assert!(matches!(page1[0].kind, BlockKind::Paragraph));
    assert_eq!(page1[0].text, "DiffLens PDF Fixture");
    assert_eq!(
        page1[1].text,
        "This is the first body paragraph spanning two lines that must merge into one block."
    );
    assert_eq!(page1[2].text, "A third paragraph after a wider gap.");
    assert!(page1[0].rect.is_some(), "pdf blocks carry bounding boxes");

    // Page 2.
    let page2: Vec<&difflens_core::Block> =
        model.blocks.iter().filter(|b| b.page == Some(2)).collect();
    assert_eq!(page2.len(), 1);
    assert_eq!(page2[0].text, "Second page text.");

    // Page 3 is blank → no text layer → scanned-pdf suspicion (1/3 > 30%).
    assert!(
        model
            .warnings
            .iter()
            .any(|w| w.contains("scanned pdf suspected") && w.contains("1 of 3"))
    );
}

#[test]
fn pdf_loader_error_message_is_actionable_when_library_is_absent() {
    // When the library is missing, the error must explain how to fix it.
    if let Err(e) = extract(&fixture("sample.pdf")) {
        let msg = e.to_string();
        assert!(
            msg.contains("PDFium library not found")
                || msg.contains("could not be bound")
                || msg.contains("failed to open pdf"),
            "unhelpful pdf error: {msg}"
        );
    }
}

// --------------------------------------------------------------------------
// DOCX
// --------------------------------------------------------------------------

#[test]
fn docx_extracts_headings_tracked_changes_table_and_warnings() {
    let model = extract(&fixture("sample.docx")).unwrap();
    assert_eq!(model.format, DocFormat::Docx);
    assert_eq!(model.page_count, None);

    assert!(matches!(
        &model.blocks[0].kind,
        BlockKind::Heading { level: 1 }
    ));
    assert_eq!(model.blocks[0].text, "Contract Summary");

    assert_eq!(
        model.blocks[1].text,
        "This agreement governs the use of the service."
    );

    // Tracked changes: accepted view keeps w:ins, drops w:del (kept in anchor).
    assert_eq!(model.blocks[2].text, "Base terms inserted clause");
    assert_eq!(model.blocks[2].anchor.as_deref(), Some("removed clause"));

    assert_eq!(
        model.blocks[3].text,
        "Payment terms follow the table below."
    );

    assert!(matches!(
        &model.blocks[4].kind,
        BlockKind::Table { rows: 2, cols: 2 }
    ));
    assert_eq!(model.blocks[4].text, "Price Amount Base fee 100 USD");

    // Tab → whitespace, line break → whitespace.
    assert_eq!(
        model.blocks[5].text,
        "Contact: admin@example.com Phone line."
    );
    assert_eq!(model.blocks.len(), 6);

    assert!(
        model
            .warnings
            .iter()
            .any(|w| w.contains("skipped 1 header/footer/footnote part(s)"))
    );
}

#[test]
fn docx_empty_document_yields_no_blocks() {
    let model = extract(&fixture("empty.docx")).unwrap();
    assert!(model.blocks.is_empty());
}

#[test]
fn docx_vietnamese_is_nfc_normalized() {
    let model = extract(&fixture("vietnamese.docx")).unwrap();
    assert_eq!(model.blocks.len(), 1);
    assert_eq!(
        model.blocks[0].text,
        "Điều khoản thanh toán trong vòng 30 ngày."
    );
}

// --------------------------------------------------------------------------
// XLSX
// --------------------------------------------------------------------------

#[test]
fn xlsx_extracts_cells_formulas_and_skips_hidden_sheets() {
    let model = extract(&fixture("sample.xlsx")).unwrap();
    assert_eq!(model.format, DocFormat::Xlsx);
    assert!(
        model
            .warnings
            .iter()
            .any(|w| w.contains("skipped 1 hidden sheet(s)"))
    );

    let cells: Vec<(&difflens_core::Block, &str, u32, u32)> = model
        .blocks
        .iter()
        .map(|b| match &b.kind {
            BlockKind::Cell { sheet, row, col } => (b, sheet.as_str(), *row, *col),
            other => panic!("unexpected kind {other:?}"),
        })
        .collect();
    assert_eq!(cells.len(), 9);

    let text_at = |sheet: &str, row: u32, col: u32| -> &str {
        cells
            .iter()
            .find(|(_, s, r, c)| *s == sheet && *r == row && *c == col)
            .map(|(b, _, _, _)| b.text.as_str())
            .unwrap()
    };
    assert_eq!(text_at("Data", 0, 0), "Item");
    assert_eq!(text_at("Data", 0, 1), "Qty");
    assert_eq!(text_at("Data", 1, 0), "Widgets");
    assert_eq!(text_at("Data", 1, 1), "3");
    assert_eq!(text_at("Data", 2, 1), "5");
    assert_eq!(text_at("Data", 3, 0), "Total");
    assert_eq!(text_at("Data", 3, 1), "SUM(B2:B3)");
    let formula_block = cells
        .iter()
        .find(|(_, s, r, c)| *s == "Data" && *r == 3 && *c == 1)
        .map(|(b, _, _, _)| *b)
        .unwrap();
    assert_eq!(formula_block.anchor.as_deref(), Some("formula"));
    assert_eq!(text_at("Notes", 0, 0), "hello world");
    // Hidden sheet must contribute nothing.
    assert!(!cells.iter().any(|(_, s, _, _)| *s == "Secret"));
}

// --------------------------------------------------------------------------
// PPTX
// --------------------------------------------------------------------------

#[test]
fn pptx_extracts_slides_in_order_with_titles_and_notes_warning() {
    let model = extract(&fixture("sample.pptx")).unwrap();
    assert_eq!(model.format, DocFormat::Pptx);
    assert_eq!(model.page_count, Some(3));
    assert_eq!(model.blocks.len(), 3);

    for (i, block) in model.blocks.iter().enumerate() {
        match &block.kind {
            BlockKind::Slide { index } => assert_eq!(*index, i as u32),
            other => panic!("unexpected kind {other:?}"),
        }
        assert_eq!(block.page, Some(i as u32 + 1));
    }
    assert_eq!(
        model.blocks[0].text,
        "Quarterly Review Revenue is up. Costs are flat."
    );
    assert_eq!(model.blocks[0].anchor.as_deref(), Some("Quarterly Review"));
    assert_eq!(model.blocks[1].text, "Plain slide text.");
    assert_eq!(model.blocks[1].anchor, None);
    assert_eq!(model.blocks[2].text, "Next Steps Ship phase 2.");
    assert_eq!(model.blocks[2].anchor.as_deref(), Some("Next Steps"));
    assert!(
        model
            .warnings
            .iter()
            .any(|w| w.contains("skipped 1 speaker-notes slide(s)"))
    );
}

// --------------------------------------------------------------------------
// Dispatch, limits and graceful degradation
// --------------------------------------------------------------------------

#[test]
fn zip_bomb_is_rejected_with_bounded_error() {
    let err = extract(&fixture("bomb.docx")).unwrap_err();
    let msg = err.to_string();
    assert!(
        msg.contains("zip bomb suspected") || msg.contains("part ceiling"),
        "unexpected error: {msg}"
    );
}

#[test]
fn entry_count_limit_is_enforced() {
    use std::io::Cursor;
    use zip::ZipWriter;
    use zip::write::SimpleFileOptions;

    let mut buf = Vec::new();
    {
        let mut writer = ZipWriter::new(Cursor::new(&mut buf));
        for i in 0..10_000 {
            writer
                .start_file(format!("filler/{i}.xml"), SimpleFileOptions::default())
                .unwrap();
            write!(&mut writer, "<x/>").unwrap();
        }
        // One entry too many, shaped like a DOCX so sniffing classifies it.
        writer
            .start_file("word/document.xml", SimpleFileOptions::default())
            .unwrap();
        write!(&mut writer, "<doc/>").unwrap();
        writer.finish().unwrap();
    }
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("many.docx");
    std::fs::write(&path, &buf).unwrap();

    let err = extract(path.to_str().unwrap()).unwrap_err();
    assert!(err.to_string().contains("entry limit"));
}

#[test]
fn extension_mismatch_warns_but_extracts() {
    let dir = tempfile::tempdir().unwrap();
    let wrong_ext = dir.path().join("looks-like.pdf");
    std::fs::copy(fixture("sample.docx"), &wrong_ext).unwrap();
    let model = extract(wrong_ext.to_str().unwrap()).unwrap();
    assert_eq!(model.format, DocFormat::Docx);
    assert!(
        model
            .warnings
            .iter()
            .any(|w| w.contains("extension suggests") && w.contains("content sniffed"))
    );
}

#[test]
fn unknown_ooxml_container_is_a_bounded_error() {
    use std::io::Cursor;
    use zip::ZipWriter;
    use zip::write::SimpleFileOptions;

    let mut buf = Vec::new();
    {
        let mut writer = ZipWriter::new(Cursor::new(&mut buf));
        writer
            .start_file("[Content_Types].xml", SimpleFileOptions::default())
            .unwrap();
        write!(&mut writer, "<Types/>").unwrap();
        writer.finish().unwrap();
    }
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("mystery.docx");
    std::fs::write(&path, &buf).unwrap();
    let err = extract(path.to_str().unwrap()).unwrap_err();
    assert!(err.to_string().contains("not a supported OOXML"));
}

#[test]
fn missing_file_is_an_error_not_a_panic() {
    let err = extract("/definitely/not/here.docx").unwrap_err();
    assert!(err.to_string().contains("cannot read"));
}

/// Fuzz-lite: truncated copies of every fixture must produce Ok or Err —
/// never a Rust-level panic. (PDFium C-layer SIGSEGV on hostile PDFs is a
/// documented, out-of-scope limitation; our fixtures are benign.)
#[test]
fn truncated_inputs_never_panic() {
    let fixtures = [
        "sample.txt",
        "empty.txt",
        "vietnamese.txt",
        "sample.pdf",
        "sample.docx",
        "empty.docx",
        "vietnamese.docx",
        "sample.xlsx",
        "sample.pptx",
        "bomb.docx",
    ];
    let dir = tempfile::tempdir().unwrap();
    for name in fixtures {
        let bytes = std::fs::read(fixture(name)).unwrap();
        let mut cut_points: Vec<usize> = vec![0, 1, 2, 3, 4, 5, 10, 50, 100];
        cut_points.push(bytes.len() / 2);
        if bytes.len() > 1 {
            cut_points.push(bytes.len() - 1);
        }
        for (round, cut) in cut_points.iter().enumerate() {
            let cut = (*cut).min(bytes.len());
            let path = dir.path().join(format!("{name}.{round}.trunc"));
            std::fs::write(&path, &bytes[..cut]).unwrap();
            // Ok or Err are both fine; a panic (or PDFium crash) fails the test.
            let _ = extract(path.to_str().unwrap());
        }
    }
}

#[test]
fn extraction_is_deterministic() {
    let first = extract(&fixture("sample.docx")).unwrap();
    let second = extract(&fixture("sample.docx")).unwrap();
    let a = serde_json::to_string(&first).unwrap();
    let b = serde_json::to_string(&second).unwrap();
    assert_eq!(a, b);
}
